// Semantic tokens / lexical scope categories
import { semanticTokenCases } from "../../harness";

const SAMPLE = [
    "// line comment",
    "import console from \"std/console\";",
    "import path from \"std/path\";",
    "const message = \"hello\";",
    "const up = message.toUpperCase();",
    "const n = 1 + 2;",
    "const inf = Infinity;",
    "const flag = true;",
    "const missing = null;",
    "let hex = 0x1F;",
    "let bin = 0b101;",
    "let big = 1_000_000;",
    "let f = 3.14e-2;",
    "let dot = .5;",
    "const arr = [1, 2, ...rest];",
    "parallel.for(0..arr.length, (i) => { arr[i] = arr[i] * 2; });",
    "setTimeout(() => print(\"later\"), 0);",
].join("\n");

semanticTokenCases("Semantic tokens: lexical categories", [
    { name: "line comment scopes as a comment", source: SAMPLE, expectScopes: [["line comment", "comment.line.double-slash.cp3"]] },
    { name: "std/console string scopes as a double-quoted string", source: SAMPLE, expectScopes: [["std/console", "string.quoted.double.cp3"]] },
    { name: "std/path string scopes as a double-quoted string", source: SAMPLE, expectScopes: [["std/path", "string.quoted.double.cp3"]] },
    { name: "console import scopes as a control keyword", source: SAMPLE, expectScopes: [["import", "keyword.control.import.cp3"]] },
    { name: "hello string scopes as a double-quoted string", source: SAMPLE, expectScopes: [["hello", "string.quoted.double.cp3"]] },
    { name: "number 1 scopes as a decimal constant", source: SAMPLE, expectScopes: [["1", "constant.numeric"]] },
    { name: "number 2 scopes as a decimal constant", source: SAMPLE, expectScopes: [["2", "constant.numeric"]] },
    { name: "Infinity scopes as a language constant", source: SAMPLE, expectScopes: [["Infinity", "constant.language.cp3"]] },
    { name: "true scopes as a language constant", source: SAMPLE, expectScopes: [["true", "constant.language.cp3"]] },
    { name: "null scopes as a language constant", source: SAMPLE, expectScopes: [["null", "constant.language.cp3"]] },
    { name: "hex literal scopes as a hex constant", source: SAMPLE, expectScopes: [["0x1F", "constant.numeric.hex.cp3"]] },
    { name: "binary literal scopes as a binary constant", source: SAMPLE, expectScopes: [["0b101", "constant.numeric.binary.cp3"]] },
    { name: "grouped decimal scopes as a decimal constant", source: SAMPLE, expectScopes: [["1_000_000", "constant.numeric.decimal.cp3"]] },
    { name: "exponent literal scopes as a decimal constant", source: SAMPLE, expectScopes: [["3.14e-2", "constant.numeric.decimal.cp3"]] },
    { name: "leading-dot literal scopes as a decimal constant", source: SAMPLE, expectScopes: [[".5", "constant.numeric.decimal.cp3"]] },
    { name: "spread operator scopes as the spread operator", source: SAMPLE, expectScopes: [["...", "keyword.operator.spread.cp3"]] },
    { name: "range operator scopes as the range operator", source: SAMPLE, expectScopes: [["..", "keyword.operator.range.cp3"]] },
    { name: "parallel scopes as a builtin namespace", source: SAMPLE, expectScopes: [["parallel", "support.namespace.cp3"]] },
    { name: "setTimeout scopes as a builtin function", source: SAMPLE, expectScopes: [["setTimeout", "support.function.builtin.cp3"]] },
    { name: "console scopes as a builtin namespace", source: SAMPLE, expectScopes: [["console", "support.namespace.cp3"]] },
    { name: "console scopes as a builtin class too", source: SAMPLE, expectScopes: [["console", "support.class.builtin.cp3"]] },
    { name: "console scopes as a builtin namespace on the second line too", source: SAMPLE, expectScopes: [["console", "support.namespace.cp3"]] },
    { name: "parallel scopes as a builtin class too", source: SAMPLE, expectScopes: [["parallel", "support.class.builtin.cp3"]] },
    { name: "toUpperCase scopes as a function call name", source: SAMPLE, expectScopes: [["toUpperCase", "entity.name.function.cp3"]] },
    { name: "arr property access scopes as a property", source: SAMPLE, expectScopes: [["arr", "variable.other.readwrite.cp3"]] },
    { name: "let keyword scopes as a storage type", source: SAMPLE, expectScopes: [["let", "storage.type.cp3"]] },
    { name: "const keyword scopes as a storage type", source: SAMPLE, expectScopes: [["const", "storage.type.cp3"]] },
    { name: "newline handling keeps the grammar stable", source: SAMPLE, expectScopes: [["message", "variable.other.readwrite.cp3"]] },
]);
